package br.com.admeclesial.application.projeto;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.domain.projeto.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.projeto.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service public class RecursoVinculadoApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final RecursoVinculadoRepository repo; final DestinacaoContribuicaoRepository destinos; final ContribuicaoRepository contribuicoes; final FonteRecursoProjetoRepository fontes; final ProjetoRepository projetos; final UtilizacaoRecursoRepository utilizacoes; final MovimentacaoFinanceiraRepository movimentos; final ContaFinanceiraRepository contas;
 public RecursoVinculadoApplicationService(RecursoVinculadoRepository r,DestinacaoContribuicaoRepository d,ContribuicaoRepository c,FonteRecursoProjetoRepository f,ProjetoRepository p,UtilizacaoRecursoRepository u,MovimentacaoFinanceiraRepository m,ContaFinanceiraRepository cf){repo=r;destinos=d;contribuicoes=c;fontes=f;projetos=p;utilizacoes=u;movimentos=m;contas=cf;}
 @Transactional public RecursoVinculado criar(RecursoVinculadoRequest r){var d=destinos.findByUuid(r.destinacaoContribuicaoUuid()).orElseThrow(()->new IllegalArgumentException("Destinação de contribuição não encontrada."));if(d.getTipo()!=TipoDestinacaoContribuicao.FINALIDADE_ESPECIFICA)throw new IllegalArgumentException("Somente destinação com finalidade específica pode gerar recurso vinculado.");if(repo.findByDestinacaoContribuicaoId(d.getId()).isPresent())throw new IllegalArgumentException("Já existe recurso vinculado para esta destinação.");var c=contribuicoes.findById(d.getContribuicaoId()).orElseThrow(()->new IllegalArgumentException("Contribuição da destinação não encontrada."));if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId());var e=new RecursoVinculado();e.setOrganizacaoEclesialId(c.getOrganizacaoEclesialId());e.setDestinacaoContribuicaoId(d.getId());e.setFinalidade(r.finalidade().trim());e.setValorOriginal(d.getValor());e.setStatus(StatusRecursoVinculado.DISPONIVEL);e.setDataCriacao(LocalDate.now());e.setObservacao(r.observacao());return repo.save(e);}
 @Transactional public FonteRecursoProjeto alocar(UUID projetoUuid,FonteRecursoProjetoRequest r){var p=projetos.findByUuid(projetoUuid).orElseThrow(()->new IllegalArgumentException("Projeto não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(p.getOrganizacaoEclesialId());if(p.getStatus()==StatusProjeto.CONCLUIDO||p.getStatus()==StatusProjeto.CANCELADO)throw new IllegalArgumentException("Projeto não pode receber recursos neste estado.");var rec=repo.findByUuid(r.recursoVinculadoUuid()).orElseThrow(()->new IllegalArgumentException("Recurso vinculado não encontrado."));if(!rec.getOrganizacaoEclesialId().equals(p.getOrganizacaoEclesialId()))throw new IllegalArgumentException("Recurso e projeto devem pertencer à mesma organização.");if(rec.getStatus()==StatusRecursoVinculado.CANCELADO)throw new IllegalArgumentException("Recurso vinculado cancelado.");var alocado=fontes.sumValorAlocadoPorRecurso(rec.getId());if(alocado.add(r.valorAlocado()).compareTo(rec.getValorOriginal())>0)throw new IllegalArgumentException("A alocação supera o valor disponível do recurso.");var e=new FonteRecursoProjeto();e.setProjetoId(p.getId());e.setRecursoVinculadoId(rec.getId());e.setValorAlocado(r.valorAlocado());e.setDescricao(r.descricao());var out=fontes.save(e);atualizarStatusRecurso(rec);return out;}
 @Transactional public UtilizacaoRecurso utilizar(UtilizacaoRecursoRequest r){var fonte=fontes.findByUuid(r.fonteRecursoProjetoUuid()).orElseThrow(()->new IllegalArgumentException("Fonte de recurso do projeto não encontrada."));var mov=movimentos.findByUuid(r.movimentacaoFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Movimentação financeira não encontrada."));if(mov.getTipo()!=TipoMovimentacaoFinanceira.SAIDA)throw new IllegalArgumentException("A utilização de recurso deve estar vinculada a uma movimentação de saída.");if(mov.getStatus()==StatusMovimentacaoFinanceira.CANCELADA)throw new IllegalArgumentException("Movimentação financeira cancelada.");var conta=contas.findById(mov.getContaFinanceiraId()).orElseThrow(()->new IllegalArgumentException("Conta financeira da movimentação não encontrada."));if(!conta.getAtivo())throw new IllegalArgumentException("Conta financeira da movimentação está inativa.");var rec=repo.findById(fonte.getRecursoVinculadoId()).orElseThrow(()->new IllegalArgumentException("Recurso vinculado não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(rec.getOrganizacaoEclesialId());if(!rec.getOrganizacaoEclesialId().equals(conta.getOrganizacaoEclesialId()))throw new IllegalArgumentException("Movimentação e recurso devem pertencer à mesma organização.");var utilizadoFonte=utilizacoes.sumValorUtilizadoPorFonte(fonte.getId());if(utilizadoFonte.add(r.valor()).compareTo(fonte.getValorAlocado())>0)throw new IllegalArgumentException("A utilização supera o valor alocado ao projeto.");var utilizadoMov=utilizacoes.sumValorUtilizadoPorMovimentacao(mov.getId());if(utilizadoMov.add(r.valor()).compareTo(mov.getValor())>0)throw new IllegalArgumentException("A utilização supera o valor da movimentação financeira.");var e=new UtilizacaoRecurso();e.setFonteRecursoProjetoId(fonte.getId());e.setMovimentacaoFinanceiraId(mov.getId());e.setValor(r.valor());e.setDescricao(r.descricao());var out=utilizacoes.save(e);atualizarStatusRecurso(rec);return out;}
 private void atualizarStatusRecurso(RecursoVinculado rec){var usadoTotal=utilizacoesTotal(rec.getId());if(usadoTotal.compareTo(rec.getValorOriginal())>=0)rec.setStatus(StatusRecursoVinculado.UTILIZADO);else if(usadoTotal.signum()>0)rec.setStatus(StatusRecursoVinculado.PARCIALMENTE_UTILIZADO);else rec.setStatus(StatusRecursoVinculado.DISPONIVEL);repo.save(rec);}
 private BigDecimal utilizacoesTotal(Long recursoId){BigDecimal total=BigDecimal.ZERO;for(var f:fontes.findAllByRecursoVinculadoIdOrderByIdAsc(recursoId)){total=total.add(utilizacoes.sumValorUtilizadoPorFonte(f.getId()));}return total;}
 @Transactional(readOnly=true) public RecursoVinculado buscar(UUID uuid){var e=repo.findByUuid(uuid).orElseThrow(()->new IllegalArgumentException("Recurso vinculado não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId());return e;}
 @Transactional(readOnly=true) public List<RecursoVinculado> listar(){return repo.findAllByOrderByDataCriacaoDesc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}
 @Transactional(readOnly=true) public List<FonteRecursoProjeto> fontes(UUID projetoUuid){var p=projetos.findByUuid(projetoUuid).orElseThrow(()->new IllegalArgumentException("Projeto não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(p.getOrganizacaoEclesialId());return fontes.findAllByProjetoIdOrderByIdAsc(p.getId());}
}
